import glob, datetime as dt
ref=dt.date(2025,8,12)
periods={
 'today':[ref,ref],
 'last_7_days':[ref-dt.timedelta(days=6),ref],
 'last_30_days':[ref-dt.timedelta(days=29),ref],
 'month_to_date':[ref.replace(day=1),ref],
}
from collections import Counter
cnt=Counter()
files=sorted(glob.glob("/app/logs/*.log"))
for p in files:
    d=dt.date.fromisoformat(p[11:21])
    for line in open(p):
        parts=line.split(None,3)
        if len(parts)<3: continue
        sev=parts[2].strip('[]')
        if sev in ('ERROR','WARNING','INFO'):
            for name,(a,b) in periods.items():
                if a<=d<=b:
                    cnt[(name,sev)]+=1
order=['today','last_7_days','last_30_days','month_to_date']
for name in order:
